begin;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where is_active and role='super_admin' order by id limit 1),true);
set local role authenticated;
do $test$
declare token text:=gen_random_uuid()::text; req uuid; batch uuid; other uuid; client uuid; item uuid; quote uuid; invoice uuid; credit uuid; rows jsonb; doc jsonb; data jsonb; failed boolean; before_count integer; stamp timestamptz;
begin
 rows:=jsonb_build_array(jsonb_build_object('name','QA Import Client','email',token||'@example.test','payment_terms','days','payment_terms_days',30)); req:=gen_random_uuid();
 batch:=public.import_commercial_batch('clients','qa-client.csv',rows,false,req);
 if public.import_commercial_batch('clients','qa-client.csv',rows,false,req)<>batch then raise exception 'Import idempotency failed'; end if;
 select record_id into client from public.import_batch_rows where batch_id=batch;
 select updated_at into stamp from public.clients where id=client;
 failed:=false; begin perform public.import_commercial_batch('clients','qa-stale.csv',jsonb_build_array(rows->0||jsonb_build_object('_import_version',stamp-interval '1 second')),true,gen_random_uuid()); exception when raise_exception then failed:=sqlerrm like '%otro usuario%'; end; if not failed then raise exception 'Stale client overwrite accepted'; end if;
 other:=public.import_commercial_batch('clients','qa-overwrite.csv',jsonb_build_array(rows->0||'{"name":"QA Import Renamed"}'::jsonb),true,gen_random_uuid());
 perform public.undo_commercial_import(other);
 if not exists(select 1 from public.clients where id=client and name='QA Import Client') then raise exception 'Client import undo failed'; end if;
 select count(*) into before_count from public.import_batches;
 failed:=false; begin perform public.import_commercial_batch('clients','qa-invalid.csv',jsonb_build_array(jsonb_build_object('name','QA Must Roll Back','email',token||'-rollback@example.test'),'{"name":"X"}'::jsonb),false,gen_random_uuid()); exception when raise_exception then failed:=true; end;
 if not failed or exists(select 1 from public.clients where email=token||'-rollback@example.test') or (select count(*) from public.import_batches)<>before_count then raise exception 'Import left partial client data'; end if;
 data:=jsonb_build_object('sku',token,'name','QA Import Item','description','QA','unit_price',10,'unit','unidad','is_active',true,'tax_rate_id',null,'manage_stock',true,'stock_quantity',5,'ideal_quantity',10,'warning_quantity',2,'supplier',null,'private_notes','Private inventory');
 other:=public.import_commercial_batch('items','qa-item.csv',jsonb_build_array(data),false,gen_random_uuid());
 select record_id into item from public.import_batch_rows where batch_id=other;
 select updated_at into stamp from public.items where id=item;
 failed:=false; begin perform public.import_commercial_batch('items','qa-stale-item.csv',jsonb_build_array(data||jsonb_build_object('_import_version',stamp-interval '1 second')),true,gen_random_uuid()); exception when raise_exception then failed:=sqlerrm like '%otro usuario%'; end; if not failed then raise exception 'Stale item overwrite accepted'; end if;
 perform public.undo_commercial_import(other);
 if not exists(select 1 from public.items where id=item and not is_active and stock_quantity=0) or (select sum(quantity) from public.inventory_movements where item_id=item)<>0 then raise exception 'Item import undo lost stock history'; end if;
 doc:=jsonb_build_object('kind','quote','document_kind','quote','client_id',client,'client_name','QA Import Client','client_email',token||'@example.test','seller_name','QA Seller','billing_address',null,'shipping_address',null,'payment_terms','days','payment_terms_days',30,'payment_method_id',null,'payment_method_name',null,'tax_exempt',false,'issue_date','2026-10-26','valid_until','2026-11-26','purchase_order',null,'project_description',null,'public_notes','Public','private_notes','Private','footer_notes','Footer','discount_mode','none','discount_value',0,'shipping_amount',0,'shipping_tax_rate',0,'items',jsonb_build_array(jsonb_build_object('item_id',null,'description','QA Service','quantity',1,'unit_price',100,'tax_rate',7,'discount_percent',0)));
 other:=public.import_commercial_batch('quotes','qa-quote.csv',jsonb_build_array(doc||jsonb_build_object('import_number','QA-'||token)),false,gen_random_uuid());
 select record_id into quote from public.import_batch_rows where batch_id=other;
 if not exists(select 1 from public.quotes where id=quote and quote_number='QA-'||token and total=107) then raise exception 'Quote import number or totals failed'; end if;
 select count(*) into before_count from public.import_batches;
 failed:=false; begin perform public.import_commercial_batch('quotes','qa-duplicate.csv',jsonb_build_array(doc||jsonb_build_object('import_number','QA-first-'||token),doc||jsonb_build_object('import_number','QA-'||token)),false,gen_random_uuid()); exception when raise_exception then failed:=true; end;
 if not failed or exists(select 1 from public.quotes where quote_number='QA-first-'||token) or (select count(*) from public.import_batches)<>before_count then raise exception 'Duplicate document left partial import'; end if;
 perform public.undo_commercial_import(other);
 if exists(select 1 from public.quotes where id=quote) then raise exception 'Quote import undo failed'; end if;
 other:=public.import_commercial_batch('invoices','qa-invoice.csv',jsonb_build_array(doc||jsonb_build_object('kind','invoice','import_number','QA-I-'||token)),false,gen_random_uuid());
 select record_id into invoice from public.import_batch_rows where batch_id=other;
 if not exists(select 1 from public.invoices where id=invoice and status='draft' and total=107) then raise exception 'Invoice import is not a draft'; end if;
 perform public.undo_commercial_import(other);
 if exists(select 1 from public.invoices where id=invoice) then raise exception 'Invoice import undo failed'; end if;
 other:=public.import_commercial_batch('credits','qa-credit.csv',jsonb_build_array(doc||'{"import_reason":"QA credit"}'::jsonb),false,gen_random_uuid());
 select record_id into credit from public.import_batch_rows where batch_id=other;
 if not exists(select 1 from public.credit_notes where id=credit and status='completed' and total=107) then raise exception 'Credit import failed'; end if;
 perform public.undo_commercial_import(other);
 if not exists(select 1 from public.credit_notes where id=credit and status='void') then raise exception 'Credit import undo did not void document'; end if;
 -- Changed rows cannot be overwritten by an undo operation.
 other:=public.import_commercial_batch('quotes','qa-changed.csv',jsonb_build_array(doc),false,gen_random_uuid());
 select record_id into quote from public.import_batch_rows where batch_id=other;
 update public.quotes set notes='Changed after importing' where id=quote;
 failed:=false; begin perform public.undo_commercial_import(other); exception when raise_exception then failed:=sqlerrm like '%cambió%'; end;
 if not failed or not exists(select 1 from public.quotes where id=quote and notes='Changed after importing') then raise exception 'Undo overwrote changed record'; end if;
end $test$;
rollback;
